for raw in p.read_text(errors='replace').splitlines():
 t=raw.strip()
 if t.startswith('export '):t=t[7:].strip()
 k,sep,val=t.partition('=')
 if sep and k.strip()==needle:
  secret=val.strip().strip('"').strip("'")
  break
out={'credential_name_found':bool(secret),'credential_length_valid':len(secret)>=16}
models={}
if len(secret)>=16:
 for label,port in [('granite',18181),('qwen3',18182),('ministral',18183),('coder',18184)]:
  req=urllib.request.Request('http://127.0.0.1:'+str(port)+'/v1/models',headers={'Authorization':'Bearer '+secret})
